:root{--color-bg:#fdf8f3;--color-bg-alt:#f3e9dd;--color-text:#2e2420;--color-text-muted:#5a4a40;--color-accent:#7a2e1d;--color-accent-on-dark:#f3c77a;--color-dark:#2e2420;--color-white:#ffffff;--font-body:Georgia,'Times New Roman',serif;--font-display:'Palatino Linotype','Book Antiqua',Georgia,serif;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--space-xl:4rem;--radius:0.5rem;--max-width:75rem;}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;font-family:var(--font-body);background-color:var(--color-bg);color:var(--color-text);line-height:1.6;font-size:1rem;}
h1,h2,h3{font-family:var(--font-display);color:var(--color-text);line-height:1.25;margin-top:0;}
p{margin-top:0;}
a{color:var(--color-accent);text-decoration:underline;}
a:hover{text-decoration:none;}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--color-accent);outline-offset:2px;}
img{max-width:100%;display:block;}
.container{width:100%;max-width:var(--max-width);margin:0 auto;padding:0 1.25rem;}

header{background-color:var(--color-dark);color:var(--color-white);}
.header-inner{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:var(--space-sm);padding:1rem 1.25rem;}
.logo{font-family:'Palatino Linotype','Book Antiqua',Georgia,serif;font-variant:small-caps;font-weight:400;letter-spacing:0.25em;font-size:clamp(1.1rem,4vw,1.6rem);color:var(--color-accent-on-dark);text-decoration:none;border-bottom:1px solid var(--color-accent-on-dark);width:fit-content;padding-bottom:0.2rem;}
.logo:hover{text-decoration:none;opacity:0.9;}
nav[aria-label="Main"] .nav-list{list-style:none;display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:0;padding:0;}
nav[aria-label="Main"] a{color:var(--color-white);text-decoration:none;font-size:0.95rem;padding:0.5rem 0.25rem;display:inline-block;}
nav[aria-label="Main"] a:hover{text-decoration:underline;}

footer{background-color:var(--color-dark);color:var(--color-white);margin-top:var(--space-xl);}
.footer-inner{padding:var(--space-lg) 1.25rem;text-align:center;}
.footer-inner p{margin:0.25rem 0;color:var(--color-bg-alt);}
.footer-name{font-family:var(--font-display);font-size:1.2rem;color:var(--color-accent-on-dark);}
.copyright{margin-top:var(--space-sm);font-size:0.85rem;color:var(--color-bg-alt);}

.btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0.75rem 1.75rem;background-color:var(--color-accent);color:var(--color-white);border:none;border-radius:var(--radius);font-size:1rem;font-family:var(--font-body);text-decoration:none;cursor:pointer;transition:background-color 0.2s ease;}
.btn:hover{background-color:#5c2316;}
.btn:focus-visible{outline:3px solid var(--color-text);outline-offset:2px;}

.card{background-color:var(--color-white);border-radius:var(--radius);padding:var(--space-md);box-shadow:0 2px 8px rgba(46,36,32,0.1);}

.grid{display:grid;gap:var(--space-md);grid-template-columns:1fr;}

form{display:grid;gap:var(--space-md);max-width:40rem;}
.form-group{display:flex;flex-direction:column;gap:0.4rem;}
label{font-weight:bold;color:var(--color-text);}
input,textarea,select{font-family:var(--font-body);font-size:1rem;padding:0.75rem;min-height:44px;border:1px solid var(--color-text-muted);border-radius:var(--radius);background-color:var(--color-white);color:var(--color-text);}
textarea{min-height:8rem;resize:vertical;}
input:focus,textarea:focus,select:focus{border-color:var(--color-accent);}

section{padding:var(--space-xl) 0;}
section:nth-of-type(even){background-color:var(--color-bg-alt);}

@media (max-width:600px){
  .header-inner{flex-direction:column;align-items:flex-start;}
  nav[aria-label="Main"] .nav-list{gap:0.5rem;}
  section{padding:var(--space-lg) 0;}
  h1{font-size:1.75rem;}
  h2{font-size:1.4rem;}
}

@media (min-width:601px){
  .grid-2{grid-template-columns:repeat(2,1fr);}
  .grid-3{grid-template-columns:repeat(3,1fr);}
  .header-inner{flex-wrap:nowrap;}
}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto;}
  *{animation:none !important;transition:none !important;}
}

